import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function optionalId(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건 형식이 올바르지 않습니다.');
  }
  return text;
}

function requiredDate(value: unknown): string {
  if (value === undefined || value === null || value === '') {
    throw new ApiError(422, 'INVALID_PERIOD', '조회 기간을 입력해 주세요.');
  }
  const text = String(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return text;
}

function numberOf(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
  }
  return n;
}

const FROM_WHERE =
  ' FROM voucher_line vl' +
  ' JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id' +
  ' JOIN account_item ai ON ai.account_item_id = vl.account_item_id' +
  ' JOIN project p ON p.project_id = vl.project_id' +
  ' JOIN department d ON d.department_id = p.department_id' +
  ' WHERE jv.voucher_date >= CAST(:startDate AS date)' +
  ' AND jv.voucher_date <= CAST(:endDate AS date)' +
  ' AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))' +
  ' AND (CAST(:projectId AS bigint) IS NULL OR vl.project_id = CAST(:projectId AS bigint))' +
  ' AND (CAST(:departmentId AS bigint) IS NULL OR p.department_id = CAST(:departmentId AS bigint))';

const GROUP_BY =
  ' GROUP BY p.project_id, p.project_code, p.project_name, d.name, ai.account_item_id, ai.account_code, ai.account_name';

@Controller('api/v1')
export class FnSfr01005Controller {
  @Get('/cost-reports')
  async listCostReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const startDate = requiredDate(q['startDate']);
    const endDate = requiredDate(q['endDate']);
    const accountItemId = optionalId(q['accountItemId']);
    const projectId = optionalId(q['projectId']);
    const departmentId = optionalId(q['departmentId']);
    const page = numberOf(q['page'], 0);
    const size = Math.min(Math.max(numberOf(q['size'], DEFAULT_SIZE), 1), MAX_SIZE);
    return transaction(async (db) => {
      const check = await db.query(
        'SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "invalid"',
        { startDate, endDate },
      );
      if (check[0]['invalid']) {
        throw new ApiError(422, 'INVALID_PERIOD', '시작일이 종료일보다 늦을 수 없습니다.');
      }
      const params = { startDate, endDate, accountItemId, projectId, departmentId };
      const items = await db.query(
        'SELECT p.project_code AS "projectCode", p.project_name AS "projectName",' +
          ' d.name AS "departmentName", ai.account_code AS "accountCode",' +
          ' ai.account_name AS "accountName", SUM(vl.amount) AS "costAmount"' +
          FROM_WHERE +
          GROUP_BY +
          ' ORDER BY p.project_code, ai.account_code' +
          ' LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size, offset: page * size },
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM (SELECT 1' + FROM_WHERE + GROUP_BY + ') t',
        params,
      );
      return {
        items: items.map((r: any) => ({ ...r, costAmount: Number(r.costAmount) })),
        page,
        size,
        total: Number(counted[0]['total']),
      };
    });
  }
}

