import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Tiles,
  Field,
  DateInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr01005Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/cost-reports', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page, role]);

  const search = () => {
    if (!startDate || !endDate) {
      notify('조회 기간을 입력해 주세요.');
      return;
    }
    if (startDate > endDate) {
      notify('시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setPage(0);
    setApplied({ startDate, endDate, accountItemId, projectId, departmentId });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setAccountItemId('');
    setProjectId('');
    setDepartmentId('');
    setPage(0);
    setApplied(null);
  };

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = items.reduce((sum, r) => sum + Number(r.costAmount), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>원가 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 원가 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>관리용 원가보고서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="회계단위(계정과목)">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="주관부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'projectCode', label: '프로젝트 코드' },
            { key: 'projectName', label: '프로젝트 명칭' },
            { key: 'departmentName', label: '부서명' },
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'costAmount', label: '원가 금액', render: (r) => <Num value={r.costAmount} /> },
          ]}
          rows={items}
          empty={loading ? '불러오는 중입니다.' : applied ? '조회 결과가 없습니다.' : '기간을 입력하고 조회해 주세요.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
    </div>
  );
}
